#!/bin/bash
set -e
echo '[pathctl] install: writing project files'

cat > package.json << 'EOF'
{
  "name": "rdk-path-control",
  "version": "1.0.5",
  "description": "RDK SD-WAN path control via local broker + bridge",
  "main": "index.js",
  "license": "ISC"
}
EOF

cat > index.js << 'EOF'
const axios = require('axios');
const mqtt = require('mqtt');

// Config injected by the Run lifecycle as env vars (see Setenv). The broker is
// the SAME local broker the clientdevices.mqtt.Bridge relays to/from IoT Core,
// so commands + acks ride the bridge exactly like rdk/ipsec/metrics does.
const PREFIX    = process.env.PATHCTL_TOPIC_PREFIX || 'rdk';
const LOCAL_API = process.env.PATHCTL_LOCAL_API   || 'http://127.0.0.1:8090/api/path';
const BROKER    = process.env.PATHCTL_BROKER_URI  || 'tcp://192.168.10.1:1883';
const CONTROL_TOPIC = PREFIX + '/path/control';
const RESULT_TOPIC  = PREFIX + '/path/control/result';
const VALID_MODES   = ['auto', 'fiber', '5g', 'tunnel1', 'tunnel2', 'tunnel3', 'tunnel4'];

console.log('[pathctl] connecting to local broker ' + BROKER);
const client = mqtt.connect(BROKER, {
  clientId: 'pathctl-' + PREFIX + '-' + Math.random().toString(36).slice(2, 10),
  reconnectPeriod: 3000,
  keepalive: 30,
});

function publishResult(body) {
  const payload = JSON.stringify(Object.assign({}, body, { ts: Date.now() }));
  client.publish(RESULT_TOPIC, payload, { qos: 1 });
  console.log('[pathctl] result:', payload);
}

client.on('connect', function () {
  console.log('[pathctl] connected to ' + BROKER + '; control=' + CONTROL_TOPIC + ' result=' + RESULT_TOPIC);
  client.subscribe(CONTROL_TOPIC, { qos: 1 }, function (err) {
    if (err) console.error('[pathctl] subscribe failed:', err.message);
    else console.log('[pathctl] subscribed; waiting for commands');
  });
});
client.on('error', function (e) { console.error('[pathctl] mqtt error:', e && e.message); });
client.on('reconnect', function () { console.log('[pathctl] reconnecting...'); });
client.on('close', function () { console.log('[pathctl] connection closed'); });

client.on('message', function (topic, payload) {
  var raw = payload.toString('utf-8');
  console.log('[pathctl] command received on ' + topic + ': ' + raw);
  var mode, id;
  try { var p = JSON.parse(raw); mode = p.mode; id = p.id; }
  catch (e) { publishResult({ ok: false, error: 'invalid JSON payload' }); return; }
  if (VALID_MODES.indexOf(mode) === -1) {
    publishResult({ id: id, ok: false, error: 'mode must be one of auto|fiber|5g|tunnel1|tunnel2|tunnel3|tunnel4', got: mode });
    return;
  }
  axios.post(LOCAL_API, { mode: mode }, { timeout: 5000, headers: { 'Content-Type': 'application/json' } })
    .then(function (res) { publishResult({ id: id, ok: true, mode: mode, httpStatus: res.status }); })
    .catch(function (e) {
      var status = e && e.response ? e.response.status : null;
      publishResult({ id: id, ok: false, mode: mode, httpStatus: status, error: e && e.message });
    });
});

// Keep the event loop alive for the lifetime of the component.
setInterval(function () {}, 1 << 30);
EOF

echo '[pathctl] install: npm install (Node-10-safe pins)'
npm install mqtt@4.3.7 axios@0.27.2 --cache /tmp/npm-cache --omit=dev
echo '[pathctl] install: done'
